import{_ as a,o as e,c as _,a3 as t}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/bei-taoyan-de-yongqi/33-阿德勒心理学是“勇气的心理学”.md","filePath":"books/bei-taoyan-de-yongqi/33-阿德勒心理学是“勇气的心理学”.md","lastUpdated":1794748679000}'),o={name:"books/bei-taoyan-de-yongqi/33-阿德勒心理学是“勇气的心理学”.md"};function n(r,p,s,i,d,c){return e(),_("div",null,[...p[0]||(p[0]=[t('<h2 id="阿德勒心理学是-勇气的心理学" tabindex="-1">阿德勒心理学是“勇气的心理学” <a class="header-anchor" href="#阿德勒心理学是-勇气的心理学" aria-label="Permalink to &quot;阿德勒心理学是“勇气的心理学”&quot;">​</a></h2><p>青年：……最终还是“勇气”问题吗？如此说来，先生您上次也说过，阿德勒心理学是“勇气心理学”。</p><p>哲人：如果再加上一点的话，那就是阿德勒心理学不是“拥有的心理学”而是“使用的心理学”。</p><p>青年：也就是“不在于被给予了什么，而在于如何去使用被给予的东西”那句话吗？</p><p>哲人：是的，你记得很清楚嘛。弗洛伊德式的原因论是“拥有的心理学”，继而就会转入决定论。另一方面，阿德勒心理学是“使用的心理学”，起决定作用的是你自己。</p><p>青年：阿德勒心理学是“勇气的心理学”，同时也是“使用的心理学”……</p><p>哲人：我们人类并不是会受原因论所说的精神创伤所摆弄的脆弱存在。从目的论的角度来讲，我们是用自己的手来选择自己的人生和生活方式。我们有这种力量。</p><p>青年：但说实话，我没有信心能够克服自卑情结，即便那是一种人生谎言，我今后恐怕也无法摆脱这种自卑情结。</p><p>哲人：为什么会那样想呢？</p><p>青年：也许先生您的话是正确的。不，我所缺乏的肯定就是勇气。我也承认人生谎言。我害怕与人打交道，不想在人际关系中受伤，所以就想回避人生课题。正因为如此才摆出了这样那样的借口。是的，就是这样。</p><p>但是，先生的话终归只是精神论吧！只不过是说些“你就是缺乏勇气，要拿出勇气来！”之类的激励的话。这就跟只会拍着别人的肩膀劝告说“拿出勇气来！”之类的愚蠢指导者一样。可是，我就是因为振作不起来才烦恼的啊！</p><p>哲人：总而言之，你就是希望听到具体对策，对吧？</p><p>青年：正是。我是人，不是机器，不可能一听到“拿出勇气”之类的指令后，就马上像加油一样地去补充勇气！</p><p>哲人：我知道了。但是，今晚也已经很晚了，所以下次我再告诉你吧。</p><p>青年：您不是在逃避吧？</p><p>哲人：当然不是。也许下一次还要讨论一下自由这个话题。</p><p>青年：不是勇气吗？</p><p>哲人：是的，是关于谈论勇气的时候所不可不提的有关自由的讨论。请你也思考一下自由是什么。</p><p>青年：自由是什么……好吧。那么，期待着下次见面。</p>',19)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
